let activeAudioElement = null;
let activeSoundCard = null;

function renderSoundPlayers() {
  const container = document.getElementById("sound-players-grid");
  if (!container) return;

  container.innerHTML = soundDataset.map((s, idx) => {
    const barsHtml = s.bars.map((h, bIdx) => 
      `<div class="waveform-bar" style="height: ${Math.round(h * 100)}%;" data-idx="${bIdx}"></div>`
    ).join("");

    return `
      <div class="sound-card" id="card-${s.id}">
        <audio id="audio-${s.id}" src="${s.file}" preload="none"></audio>
        
        <div>
          <div class="sound-card-header">
            <span class="sound-specimen-pill">${s.specimen}</span>
            <span class="sound-format-badge">${s.format}</span>
          </div>
          
          <h4 class="sound-card-title">${s.title}</h4>
          <p class="sound-card-character">${s.desc}</p>
        </div>

        <div>
          <div class="sound-waveform-track" id="track-${s.id}" title="Click waveform to seek">
            ${barsHtml}
          </div>

          <div class="sound-controls-row">
            <button class="sound-play-btn" id="btn-${s.id}" type="button" aria-label="Play recording">
              <span class="btn-play-icon">▶</span>
              <span class="btn-label-text">LISTEN</span>
            </button>
            <span class="sound-time-readout" id="time-${s.id}">0:00 / 0:0${Math.round(s.dur)}</span>
            <span class="sound-status-dot">
              <span class="status-indicator-circle"></span>
              <span class="status-label" id="status-${s.id}">IDLE</span>
            </span>
          </div>
        </div>
      </div>
    `;
  }).join("");

  // Attach event listeners to each sound card
  soundDataset.forEach(s => {
    const audio = document.getElementById(`audio-${s.id}`);
    const card = document.getElementById(`card-${s.id}`);
    const btn = document.getElementById(`btn-${s.id}`);
    const timeEl = document.getElementById(`time-${s.id}`);
    const statusEl = document.getElementById(`status-${s.id}`);
    const track = document.getElementById(`track-${s.id}`);
    if (!audio || !card || !btn || !track) return;

    const bars = track.querySelectorAll(".waveform-bar");

    function resetThisPlayer() {
      audio.pause();
      audio.currentTime = 0;
      card.classList.remove("is-playing");
      btn.innerHTML = '<span class="btn-play-icon">▶</span> <span class="btn-label-text">LISTEN</span>';
      timeEl.textContent = `0:00 / 0:0${Math.round(s.dur)}`;
      statusEl.textContent = "IDLE";
      bars.forEach(b => {
        b.classList.remove("passed");
        b.classList.remove("active-bar");
      });
    }

    btn.addEventListener("click", () => {
      if (!audio.paused) {
        // Currently playing: pause it
        audio.pause();
        card.classList.remove("is-playing");
        btn.innerHTML = '<span class="btn-play-icon">▶</span> <span class="btn-label-text">LISTEN</span>';
        statusEl.textContent = "PAUSED";
      } else {
        // Stop any other playing audio on the page
        if (activeAudioElement && activeAudioElement !== audio) {
          activeAudioElement.pause();
          if (activeSoundCard) {
            activeSoundCard.classList.remove("is-playing");
            const prevBtn = activeSoundCard.querySelector(".sound-play-btn");
            if (prevBtn) prevBtn.innerHTML = '<span class="btn-play-icon">▶</span> <span class="btn-label-text">LISTEN</span>';
            const prevStatus = activeSoundCard.querySelector(".status-label");
            if (prevStatus) prevStatus.textContent = "IDLE";
          }
        }

        activeAudioElement = audio;
        activeSoundCard = card;

        audio.play().then(() => {
          card.classList.add("is-playing");
          btn.innerHTML = '<span class="btn-play-icon">❚❚</span> <span class="btn-label-text">PAUSE</span>';
          statusEl.textContent = "PLAYING";
        }).catch(err => {
          console.warn("Audio playback interrupted or blocked:", err);
        });
      }
    });

    audio.addEventListener("timeupdate", () => {
      if (!audio.duration) return;
      const cur = audio.currentTime;
      const dur = audio.duration;
      const curSec = Math.floor(cur);
      const curMs = Math.floor((cur % 1) * 10);
      timeEl.textContent = `0:0${curSec}.${curMs} / 0:0${Math.round(dur)}`;

      const progress = cur / dur;
      const activeIdx = Math.min(bars.length - 1, Math.floor(progress * bars.length));

      bars.forEach((b, idx) => {
        if (idx < activeIdx) {
          b.classList.add("passed");
          b.classList.remove("active-bar");
        } else if (idx === activeIdx) {
          b.classList.add("passed");
          b.classList.add("active-bar");
        } else {
          b.classList.remove("passed");
          b.classList.remove("active-bar");
        }
      });
    });

    audio.addEventListener("ended", () => {
      resetThisPlayer();
      if (activeAudioElement === audio) {
        activeAudioElement = null;
        activeSoundCard = null;
      }
    });

    // Click track to seek
    track.addEventListener("click", (e) => {
      const rect = track.getBoundingClientRect();
      const clickX = e.clientX - rect.left;
      const frac = Math.max(0, Math.min(1, clickX / rect.width));
      if (audio.duration) {
        audio.currentTime = frac * audio.duration;
      }
      if (audio.paused) {
        btn.click();
      }
    });
  });
}

function renderPowertrainChart() {
  const container = document.getElementById("powertrain-chart-container");
  const legendContainer = document.getElementById("engine-legend-container");
  if (!container) return;

  // Render Stacked Bars
  container.innerHTML = powertrainDecades.map(dec => {
    const slicesHtml = Object.entries(powertrainMeta).map(([k, meta]) => {
      const pct = dec[k] || 0;
      if (pct === 0) return "";
      const isWide = pct >= 8;
      return `
        <div class="engine-slice" style="width: ${pct}%; background-color: ${meta.hex};" title="${meta.label}: ${pct}% in ${dec.decade}">
          ${isWide ? `${meta.label.split(" ")[0]} ${pct}%` : ""}
        </div>
      `;
    }).join("");

    return `
      <div class="engine-decade-row">
        <div class="engine-meta-row">
          <span class="engine-decade-label">${dec.decade}</span>
          <span class="engine-dominant-tag">Dominant: <strong>${dec.dominant}</strong> &bull; ${dec.n.toLocaleString()} models</span>
        </div>
        <div class="engine-stacked-bar">
          ${slicesHtml}
        </div>
      </div>
    `;
  }).join("");

  // Render Legend
  if (legendContainer) {
    legendContainer.innerHTML = Object.entries(powertrainMeta).map(([k, meta]) => `
      <div class="engine-legend-item">
        <span class="engine-legend-dot" style="background-color: ${meta.hex};"></span>
        <span>${meta.label}</span>
      </div>
    `).join("");
  }
}



function initSoundVisuals() {
  if (typeof renderSoundPlayers === 'function') {
    renderSoundPlayers();
  }
  if (typeof renderPowertrainChart === 'function') {
    renderPowertrainChart();
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initSoundVisuals);
} else {
  initSoundVisuals();
}
